const row = $json ?? {};
const state = $('Load Task State').first().json ?? {};
return [{
  json: {
    ...state,
    worker_run_id: String(row.worker_run_id ?? state.worker_run_id ?? ''),
    worker_status: String(row.worker_status ?? ''),
    worker_output: String(row.worker_output ?? ''),
    worker_error: String(row.worker_error ?? ''),
    hermes_error: String(row.worker_error ?? ''),
    worker_route: String(row.worker_status ?? '').toLowerCase() === 'completed' ? 'completed' : 'permanent_failure',
    error: String(row.worker_error ?? '')
  }
}];

const row = $json ?? {};
const state = $('Load Task State').first().json ?? {};
return [{
  json: {
    ...state,
    reviewer_run_id: String(row.reviewer_run_id ?? state.reviewer_run_id ?? ''),
    reviewer_status: String(row.reviewer_status ?? ''),
    reviewer_output: String(row.reviewer_output ?? ''),
    reviewer_error: String(row.reviewer_error ?? ''),
    hermes_error: String(row.reviewer_error ?? ''),
    reviewer_route: String(row.reviewer_status ?? '').toLowerCase() === 'completed' ? 'completed' : 'permanent_failure',
    error: String(row.reviewer_error ?? '')
  }
}];

const review = $('Parse Review').last().json ?? {};
const state = $('Load Task State').first().json ?? {};
const plan = JSON.parse(String(state.plan_json ?? '{}'));
const task = plan.tasks?.[Number(state.task_index ?? 0)] ?? {};
const taskId = String(task.id ?? '');
const reviewMessage = [
  '🧪 REVIEW RESULT',
  `Task: ${taskId}`,
  `Status: ${String(review.review_status ?? '')}`,
  `Score: ${String(review.review_score ?? 0)}`,
  String(review.review_reason ?? ''),
  review.review_next_task ? `Next: ${String(review.review_next_task)}` : ''
].filter(Boolean).join('\n');
return [{json:{...state,...review,review_message:reviewMessage}}];

function last(name) {
  try { const items=$(name).all(); return items.length ? items[items.length-1].json : null; }
  catch (_) { return null; }
}
const failure=$json;
const saved=last('Load Task State') ?? {};
const planText=String(saved.plan_json ?? '').trim();
let tasks=[];
let planSummary='';
if (planText) {
  try {
    const plan=JSON.parse(planText);
    tasks=Array.isArray(plan.tasks) ? plan.tasks : [];
    planSummary=String(plan.summary ?? '');
  } catch (_) {}
}
